import{_ as r,C as s,o as t,c as l,j as a,a as i,b as c,w as n,E as d,a2 as h,a3 as u}from"./chunks/framework.pb1iZPmZ.js";const S=JSON.parse('{"title":"Project Pitches: 30-Second & 2-Minute Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),p={name:"00b-project-pitch.md"};function g(m,e,f,y,v,b){const o=s("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"project-pitches-30-second-2-minute-interview-scripts",tabindex:"-1"},[i("Project Pitches: 30-Second & 2-Minute Interview Scripts "),a("a",{class:"header-anchor",href:"#project-pitches-30-second-2-minute-interview-scripts","aria-label":'Permalink to "Project Pitches: 30-Second & 2-Minute Interview Scripts"'},"​")],-1)),(t(),c(h,null,{default:n(()=>[d(o,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P30%5B%2230-Second%20Elevator%20Pitch%22%5D%20--%3E%20Core%5B%22Core%20Value%3A%20Hospital%20Staff%20Auth%20Gateway%22%5D%0A%20%20%20%20P30%20--%3E%20Stack%5B%22Stack%3A%20Express%205%20%2B%20MongoDB%20%2B%20connect-mongo%22%5D%0A%20%20%20%20%0A%20%20%20%20P2M%5B%222-Minute%20Deep%20Pitch%22%5D%20--%3E%20Arch%5B%22Architecture%3A%20Stateful%20Sessions%20in%20MongoDB%22%5D%0A%20%20%20%20P2M%20--%3E%20Front%5B%22Frontend%3A%203D%20Parallax%20%26%20Pure%20CSS%20Glassmorphism%22%5D%0A%20%20%20%20P2M%20--%3E%20Sec%5B%22Security%20%26%20Tradeoffs%3A%20Plaintext%20vs%20Argon2%2C%20Session%20Invalidation%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=u('<hr><h2 id="_1-the-30-second-elevator-pitch" tabindex="-1">1. The 30-Second Elevator Pitch <a class="header-anchor" href="#_1-the-30-second-elevator-pitch" aria-label="Permalink to &quot;1. The 30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built the Sachidanand Member Access Portal, a secure, full-stack authentication gateway designed for hospital staff and healthcare affiliates. It runs on Node.js and Express 5 with MongoDB and Mongoose, using stateful server sessions backed by <code>connect-mongo</code> so active clinical logins survive server restarts. On the client side, I built an interactive glassmorphic interface with pure CSS and a custom 3D mouse parallax tilt engine in vanilla JavaScript, completely avoiding heavy UI framework overhead. It demonstrates end-to-end full-stack state management, secure session destruction, and server-side EJS rendering for protected hospital dashboards.&quot;</p></blockquote><hr><h2 id="_2-the-2-minute-architectural-pitch" tabindex="-1">2. The 2-Minute Architectural Pitch <a class="header-anchor" href="#_2-the-2-minute-architectural-pitch" aria-label="Permalink to &quot;2. The 2-Minute Architectural Pitch&quot;">​</a></h2><blockquote><p>&quot;In a healthcare setting, clinician terminals need immediate, rock-solid perimeter access control without unnecessary frontend bundle bloat or complex SPA hydration issues. I engineered this portal as a lightweight, full-stack Node.js and Express web application backed by MongoDB.</p><p>When an employee arrives at the portal, they are greeted by an interactive glassmorphic login card. Instead of using a bulky React or Three.js bundle, I implemented the 3D mouse parallax tilt in pure vanilla JavaScript by calculating cursor offsets relative to the viewport center and clamping rotation angles to ten degrees on the GPU. The interface allows seamless sliding between account registration and login via hardware-accelerated CSS transforms.</p><p>On the backend, I chose stateful session authentication over stateless JWTs. Many engineers default to JWTs, but in a clinical hospital environment, you need instantaneous session revocation—if a nurse logs out or an employee badge is revoked, you must immediately invalidate that session without waiting for a token to expire. I integrated <code>express-session</code> with <code>connect-mongo</code>, serializing session identifiers into a dedicated MongoDB collection with automated TTL expiration indexes.</p><p>When a user logs in, the backend authenticates their credentials against the <code>employees</code> collection and serializes their user ID into the MongoDB session store. A global hydration middleware intercepts authenticated requests, fetches the employee document, and populates <code>res.locals.user</code>. Protected routes like <code>/dashboard</code> verify session presence before rendering dynamic EJS templates on the server, ensuring zero unauthorized access.</p><p>If I were taking this architecture into a high-security HIPAA production deployment today, my immediate priority would be upgrading password persistence from the current prototype plaintext storage to Argon2id with salting, adding Redis as the high-throughput session cache layer ahead of MongoDB, and integrating clinical multi-factor authentication.&quot;</p></blockquote><hr><h2 id="_3-delivery-guidance-for-interviews" tabindex="-1">3. Delivery Guidance for Interviews <a class="header-anchor" href="#_3-delivery-guidance-for-interviews" aria-label="Permalink to &quot;3. Delivery Guidance for Interviews&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Factor</th><th style="text-align:left;">What to Emphasize</th><th style="text-align:left;">Common Trap to Avoid</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pacing</strong></td><td style="text-align:left;">Speak calmly and deliberately. Take a 1-second pause after mentioning stateful sessions.</td><td style="text-align:left;">Do not rush through the dependencies or speak in a monotone list.</td></tr><tr><td style="text-align:left;"><strong>Tone</strong></td><td style="text-align:left;">Confident, analytical, and aware of architectural tradeoffs (e.g., admitting plaintext password storage as a prototype limitation).</td><td style="text-align:left;">Never pretend the prototype is an enterprise-ready HIPAA system; frame it as an architectural foundation ready for hardening.</td></tr><tr><td style="text-align:left;"><strong>Visual Cues</strong></td><td style="text-align:left;">Point to the session store in MongoDB and the 3D tilt engine when screen-sharing the demo.</td><td style="text-align:left;">Avoid getting bogged down in CSS syntax; keep focus on performance and GPU acceleration.</td></tr></tbody></table>',9))])}const w=r(p,[["render",g]]);export{S as __pageData,w as default};
